"use strict";

/**
 * Draw a 720p Canvas, this time, sticking with 2D, so not indicating a renderer
*/
function setup() {
    createCanvas(1280, 720);
}


/**
 * Draw The Juggler
*/
function draw() {
    ellipse(500, 500, 100);
}